import json
from pathlib import Path
P=Path(__file__).resolve().parent
rs=json.loads((P/'remaining-initial.json').read_text());done={x['Form_ID'] for f in P.glob('pass*-saved-assignments.json') for x in json.loads(f.read_text())}
groups=[{'parent': '6225', 'gloss': ['rope'], 'forms': ['doir', 'ḍoṛi', 'ḍūṛi', 'ḍõriā'], 'citation': 'CDIAL[6225 and addenda]', 'evidence': 'Turner explicitly includes Bihari ḍor/ḍorī, Oriya ḍora/ḍori and Gujarati/Marathi dorī in the davara string/rope family. These survey responses preserve the diagnostic d/ḍ–r skeleton; the eastern diphthong and the Tharu nasal vowel and ending are retained as regional qualifications. The additional-retroflex doiḍ-/doḷḍ- forms are excluded.'}, {'parent': '5227-3', 'gloss': ['rope'], 'forms': ['jaᵘro', 'jauri', 'jeōrʰī', 'jā̃ᵘr', 'jeura', 'jevli', 'jevvḍi', 'jevḍa', 'jevḍi', 'jīvḷa'], 'citation': 'CDIAL[5227,2,ḍa extension and addenda]', 'evidence': 'Turner identifies the ḍa extension of jīvā separately, with Punjabi jeuṛī/jeuṛā, Kumaoni jyoṛo, Nepali jiuri, Bihari jaurī and Gujarati jevrī. The Dotyali/eastern and Haryanvi/Mewari forms fit this extended rope family, with regional rhotic/lateral/retroflex realizations. This does not include the ambiguous joḍā response or the SSNP y-spelling requiring its own font check.'}, {'parent': '3408', 'gloss': ['broom'], 'forms': ['kutso'], 'languages': ['Dotyali'], 'citation': 'CDIAL[3408]', 'evidence': 'Turner explicitly gives Kumaoni kuco brush and Gangoli kuċ broomstick, with Nepali kuco brush/broom. Dotyali kutso has the corresponding affricate written ts and the same broom sense; this fits kūrca rather than the other unrelated broom roots.'}, {'parent': '9188', 'gloss': ['broom'], 'forms': ['bahrī', 'bāhrī', 'bhārī', 'bārī', 'bʰārī', 'bʰāṛī'], 'languages': ['RathwiBareli', 'Bhilali', 'awan', 'Goj'], 'citation': 'CDIAL[9188 and addenda]', 'evidence': 'Turner lists Punjabi bahārī/buhārī and Lahnda bohārī broom, with Prakrit baühārī/bōhārī and Gujarati bārvũ sweep. The contracted bāh-/bhā-rī survey forms fit this northwestern and western broom family. This is a qualified comparative placement allowing contraction and aspiration displacement; obscure retroflex-expanded and tonal p-initial forms are excluded, as is the explicitly uncertain Gawri comparison under vardhana.'}, {'parent': '13014', 'gloss': ['broom'], 'forms': ['sarɔṇi'], 'languages': ['Nimadi'], 'citation': 'CDIAL[13014,2]', 'evidence': 'Turner distinguishes saṁvaraṇa putting in order, with Gujarati sāvarṇi broom, from saṁvaraṇa enclosure. Nimadi sarɔṇi matches the broom noun with contracted medial v; this is an explicitly regional comparison, not a claim that every eastern s/h broom word shares this origin.'}]
a=[]
for i,g in enumerate(groups):
 for r in rs:
  if r['ID'] not in done and r['Gloss'] in g['gloss'] and r['Form'] in g['forms'] and ('languages' not in g or r['Language_ID'] in g['languages']):
   a.append(dict(record=r,parent=g['parent'],kind='reflex',citation=g['citation'],evidence=g['evidence'],family=i))
assert len(a)==len({x['record']['ID'] for x in a})
h=[]
(P/'pass039-decisions.json').write_text(json.dumps(dict(accepted=a,held=h),ensure_ascii=False,indent=1)+'\n')
(P/'pass039-rules.json').write_text(json.dumps(groups,ensure_ascii=False,indent=1)+'\n')
print(len(a),'accepted',len(h),'held',[(g['parent'],sum(x['family']==i for x in a)) for i,g in enumerate(groups)])
